SELECT fr.id, fr.task_id, ft.task_no, fr.patient_id, p.name AS patient_name,
       fr.doctor_id, u.name AS doctor_name, fr.followup_date, fr.followup_type,
       fr.symptoms, fr.blood_pressure, fr.blood_sugar, fr.weight,
       fr.medication_compliance, fr.adverse_reactions, fr.lifestyle_guidance,
       fr.next_followup_date, fr.followup_result, fr.remarks
FROM followup_record fr
LEFT JOIN followup_task ft ON fr.task_id = ft.id
LEFT JOIN patient p ON fr.patient_id = p.id
LEFT JOIN doctor d ON fr.doctor_id = d.id
LEFT JOIN user u ON d.user_id = u.id


        AND fr.patient_id = #{patientId}


        AND fr.doctor_id = #{doctorId}


        AND fr.task_id = #{taskId}


        AND fr.followup_date >= #{startDate}


        AND fr.followup_date <= #{endDate}


ORDER BY fr.followup_date DESC, fr.create_time DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM followup_record fr


        AND fr.patient_id = #{patientId}


        AND fr.doctor_id = #{doctorId}


        AND fr.task_id = #{taskId}


        AND fr.followup_date >= #{startDate}


        AND fr.followup_date <= #{endDate}

